51	/* ── Collection gauge ── */
52	function Ring({ pct }: { pct: number }) {
53	  const cx = 65, cy = 65, r = 48, diskR = 37;
54	  const circ = 2 * Math.PI * r;
55	  const p = Math.max(0.01, Math.min(1, pct));
56	  const endAng = (135 + 360 * p) * Math.PI / 180;
57	  return (
58	    <svg width="130" height="130" viewBox="0 0 130 130" style={{ display: 'block' }}>
59	      <defs>
60	        <filter id="pg-disk" x="-90%" y="-90%" width="280%" height="280%">
61	          <feDropShadow dx="0" dy="2.5" stdDeviation="7" floodColor="rgba(4,13,109,0.22)" />
62	        </filter>
63	        <filter id="pg-arc" x="-80%" y="-80%" width="260%" height="260%">
64	          <feDropShadow dx="0" dy="0.5" stdDeviation="4" floodColor="#040D6D" floodOpacity="0.32" />
65	        </filter>
66	      </defs>
67	      <circle cx={cx} cy={cy} r={diskR} fill="#EAEAEA" filter="url(#pg-disk)" />
68	      <circle cx={cx} cy={cy} r={r} fill="none" stroke="#FFFFFF" strokeOpacity="0.8" strokeWidth="1.5" />
69	      <circle cx={cx} cy={cy} r={r} fill="none" stroke={C.navy} strokeWidth="2.5" strokeLinecap="round"
70	        strokeDasharray={`${circ * p} ${circ}`} transform={`rotate(135 ${cx} ${cy})`} filter="url(#pg-arc)" />
71	      <circle cx={cx + r * Math.cos(endAng)} cy={cy + r * Math.sin(endAng)} r="5.5" fill={C.navy} filter="url(#pg-arc)" />
72	      <text x={cx} y={cy + 6} textAnchor="middle" fontFamily="system-ui,sans-serif" fontWeight="400" fontSize="19" fill={C.navy}>
73	        {Math.round(p * 100)}%
74	      </text>
75	    </svg>
76	  );
77	}
78	
79	/* ── Stat icon SVGs ── */
80	function IcoTenants() {
81	  return <svg width={17} height={17} viewBox="0 0 24 24" fill={C.navy}><circle cx="8.5" cy="8" r="3"/><circle cx="16" cy="8.5" r="2.4"/><path d="M2.6 19c0-3.2 2.6-5.6 5.9-5.6s5.9 2.4 5.9 5.6z"/><path d="M15.4 13.6c2.6.2 4.9 2.3 4.9 5.1"/></svg>;
82	}
83	function IcoWarn() {
84	  return <svg width={17} height={17} viewBox="0 0 24 24" fill="none" stroke={C.navy} strokeWidth="1.8" strokeLinecap="round"><path d="M12 3.6 21 19H3z"/><path d="M12 10v4.1"/><circle cx="12" cy="16.6" r=".95" fill={C.navy} stroke="none"/></svg>;
85	}
86	function IcoPage() {
87	  return <svg width={17} height={17} viewBox="0 0 24 24" fill="none" stroke={C.navy} strokeWidth="1.8" strokeLinecap="round"><path d="M6 3h8l4 4v14H6z"/><path d="M14 3v4h4"/><path d="M9 12h6M9 15.5h6"/></svg>;
88	}
89	function IcoPause() {
90	  return <svg width={17} height={17} viewBox="0 0 24 24" fill={C.navy}><rect x="6.5" y="4.5" width="3.6" height="15" rx="1.3"/><rect x="13.9" y="4.5" width="3.6" height="15" rx="1.3"/></svg>;
91	}
92	
93	const STAT_ICONS = [IcoTenants, IcoWarn, IcoPage, IcoPause];
94	
95	export default function PropertyDashboard() {
96	  const [, setLocation] = useLocation();
97	
98	  const { data: tenants = [] } = useQuery<any[]>({
99	    queryKey: ['/api/property/tenants'],
100	    queryFn: () => propFetch('/api/property/tenants').then(r => { if (!r.ok) throw new Error('load failed'); return r.json(); }),
101	    staleTime: 60000,
102	    retry: false,
103	  });
104	
105	  const { data: invoices = [], isLoading: invLoading, isError: invError, refetch: refetchInv } = useQuery<any[]>({
106	    queryKey: ['/api/property/invoices'],
107	    queryFn: () => propFetch('/api/property/invoices').then(r => { if (!r.ok) throw new Error('load failed'); return r.json(); }),
108	    staleTime: 30000,
109	    retry: false,
110	  });
111	
112	  const { data: schedules = [] } = useQuery<any[]>({
113	    queryKey: ['/api/property/schedules'],
114	    queryFn: () => propFetch('/api/property/schedules').then(r => { if (!r.ok) throw new Error('load failed'); return r.json(); }),
115	    staleTime: 60000,
116	    retry: false,
117	  });
118	
119	  /* Derived stats — voided invoices are excluded from collection/recent so a
120	     cancelled request never drags down the rate or shows as a live payment. */
121	  const liveInvoices    = invoices.filter((i: any) => i.status !== 'voided');
122	  const activeTenants   = tenants.filter((t: any) => t.status !== 'archived').length;
123	  const overdueCount    = invoices.filter((i: any) => i.status === 'overdue').length;
124	  const queuedCount     = invoices.filter((i: any) => i.status === 'pending_dispatch').length;
125	  const activeCount     = invoices.filter((i: any) => ['pending_dispatch', 'dispatched', 'overdue', 'dispatch_failed'].includes(i.status)).length;
126	  const paidCount       = liveInvoices.filter((i: any) => i.status === 'paid' || i.status === 'paid_external').length;
127	  const collectionPct   = liveInvoices.length > 0 ? paidCount / liveInvoices.length : 0;
128	
129	  const now = new Date();
130	  const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
131	  const monthlyRevenue = invoices
132	    .filter((i: any) => (i.status === 'paid' || i.status === 'paid_external') && i.paidAt && new Date(i.paidAt) >= monthStart)
133	    .reduce((s: number, i: any) => s + (i.amountCents ?? 0), 0);
134	
135	  const recent = [...liveInvoices]
136	    .sort((a: any, b: any) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())
137	    .slice(0, 3);
138	
139	  const stats = [
140	    { label: 'tenants',     v: activeTenants, Ico: STAT_ICONS[0] },
141	    { label: 'outstanding', v: overdueCount,  Ico: STAT_ICONS[1] },
142	    { label: 'queued',      v: queuedCount,   Ico: STAT_ICONS[2] },
143	    { label: 'paused',      v: schedules.filter((s: any) => s.status === 'paused').length, Ico: STAT_ICONS[3] },
144	  ];
145	
146	  return (
147	    <div style={{ background: C.white, minHeight: '100svh', display: 'flex', justifyContent: 'center' }}>
148	    <div style={{ width: '100%', maxWidth: 430, minHeight: '100svh', background: '#F4F4F4', paddingBottom: 130, fontFamily: "'Outfit', system-ui, sans-serif" }}>
149	      <div style={{ height: 54 }} />
150	
151	      {/* Load error — show a retry instead of silently rendering zeros */}
152	      {invError && (
153	        <div style={{ margin: '0 18px 12px', padding: '14px 16px', borderRadius: 16, background: 'rgba(255,59,78,0.08)', border: '1px solid rgba(255,59,78,0.2)', display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 12 }}>
154	          <span style={{ color: '#C71A2A', fontSize: 13, fontWeight: 500 }}>{invLoading ? 'loading…' : "couldn't load your data"}</span>
155	          <button onClick={() => refetchInv()} style={{ background: C.navy, color: C.white, border: 'none', borderRadius: 10, padding: '8px 14px', fontSize: 12, fontWeight: 700, cursor: 'pointer' }}>retry</button>
156	        </div>
157	      )}
158	
159	      {/* 1 — Active transaction hero */}
160	      <div style={{ padding: '0 18px' }}>
161	        <div style={{ background: C.navy, borderRadius: 24, padding: '24px 26px 26px' }}>
162	          <div style={{ fontWeight: 900, fontSize: 62, color: C.sky, letterSpacing: '-0.04em', lineHeight: 0.92, fontVariantNumeric: 'tabular-nums' }}>
163	            {activeCount}
164	          </div>
165	          <div style={{ fontWeight: 500, fontSize: 12, color: C.sky, letterSpacing: '0.16em', textTransform: 'uppercase', marginTop: 6 }}>
166	            active transaction{activeCount !== 1 ? 's' : ''}
167	          </div>
168	          <div style={{ marginTop: 18, height: 24, borderRadius: 999, border: `1.5px solid ${C.sky}`, padding: 3 }}>
169	            <div style={{ width: `${Math.max(4, collectionPct * 100)}%`, height: '100%', borderRadius: 999, background: C.sky, transition: 'width 0.8s ease' }} />
170	          </div>
171	        </div>
172	      </div>
173	
174	      {/* 2 — Revenue + gauge row */}
175	      <div style={{ display: 'grid', gridTemplateColumns: '1.32fr 1fr', gap: 14, padding: '16px 18px 0' }}>
176	        <div style={{ background: C.sky, borderRadius: 22, padding: '24px 22px', display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
177	          <div style={{ fontWeight: 900, fontSize: 36, color: C.navy, letterSpacing: '-0.04em', lineHeight: 1, fontVariantNumeric: 'tabular-nums' }}>
178	            {fmtCents(monthlyRevenue)}
179	          </div>
180	          <div style={{ fontWeight: 500, fontSize: 11, color: C.navy, letterSpacing: '0.08em', textTransform: 'uppercase', marginTop: 12, lineHeight: 1.3 }}>
181	            monthly rent<br />revenue
182	          </div>
183	        </div>
184	        <div style={{ background: '#F2F0F0', borderRadius: 22, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
185	          <Ring pct={collectionPct} />
186	        </div>
187	      </div>
188	
189	      {/* 3 — Stat strip */}
190	      <div style={{ padding: '16px 18px 0' }}>
191	        <div style={{ background: C.navy, borderRadius: 24, padding: '18px 16px' }}>
192	          <div style={{ border: '2px solid rgba(88,171,255,0.55)', borderRadius: 20, padding: 10, display: 'grid', gridTemplateColumns: 'repeat(4,1fr)', gap: 13 }}>
193	            {stats.map(({ label, v, Ico }) => (
194	              <div key={label} style={{ borderRadius: 18, padding: '12px 11px', background: C.sky, minHeight: 92, display: 'flex', flexDirection: 'column', justifyContent: 'flex-start', boxSizing: 'border-box' }}>
195	                <div style={{ marginBottom: 8 }}><Ico /></div>
196	                <div style={{ fontWeight: 700, fontSize: 7.5, color: C.navy, letterSpacing: '0.06em', textTransform: 'uppercase', marginBottom: 6, whiteSpace: 'nowrap' }}>{label}</div>
197	                <div style={{ fontWeight: 800, fontSize: 28, color: C.white, letterSpacing: '-0.03em', lineHeight: 1, fontVariantNumeric: 'tabular-nums' }}>{v}</div>
198	              </div>
199	            ))}
200	          </div>
201	        </div>
202	      </div>
203	
204	      {/* 4 — Rent transactions */}
205	      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '22px 20px 12px' }}>
206	        <div style={{ fontWeight: 600, fontSize: 12, color: C.navy, letterSpacing: '0.12em', textTransform: 'uppercase' }}>rent transactions</div>
207	        <button onClick={() => setLocation('/property/tenants')} style={{ fontSize: 13, fontWeight: 600, color: C.btn, background: 'none', border: 'none', cursor: 'pointer' }}>view all →</button>
208	      </div>
209	
210	      {recent.length === 0 ? (
211	        <div style={{ padding: '32px 18px', textAlign: 'center', color: C.mute, fontSize: 13 }}>
212	          no transactions yet — add tenants to get started
213	        </div>
214	      ) : (
215	        <div style={{ display: 'flex', flexDirection: 'column', gap: 12, padding: '0 18px' }}>
216	          {recent.map((inv: any) => {
217	            const name     = inv.tenantName || '—';
218	            const initials = name.split(' ').map((w: string) => w[0]).join('').slice(0, 2).toUpperCase();
219	            return (
220	              <div key={inv.id} style={{ ...GLASS, borderRadius: 18, padding: '14px 16px', display: 'flex', alignItems: 'center', gap: 13 }}>
221	                <div style={{ width: 40, height: 40, borderRadius: 999, background: C.navy, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0, fontWeight: 800, fontSize: 12, color: C.sky, letterSpacing: '0.03em' }}>
222	                  {initials}
223	                </div>
224	                <div style={{ flex: 1, minWidth: 0 }}>
225	                  <div style={{ fontWeight: 500, fontSize: 13.5, color: C.navy, textTransform: 'capitalize', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{name}</div>
226	                  <div style={{ fontWeight: 400, fontSize: 11, color: C.mute, marginTop: 2, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{inv.propertyAddress || '—'}</div>
227	                </div>
228	                <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: 5, flexShrink: 0 }}>
229	                  {(() => {
230	                    const isSplit = inv.splitEnabled && inv.splitCount > 1;
231	                    const paid = inv.splitPaidCount || 0;
232	                    const showOwing = isSplit && paid > 0 && invoiceStatus(inv) !== 'paid';
233	                    return (
234	                      <>
235	                        <div style={{ fontWeight: 700, fontSize: 14, color: C.navy, fontVariantNumeric: 'tabular-nums' }}>{fmtCents(showOwing ? (inv.owingCents ?? inv.amountCents) : (inv.amountCents ?? 0))}</div>
236	                        {isSplit && <div style={{ fontSize: 9.5, fontWeight: 700, color: '#0B7D63' }}>{paid}/{inv.splitCount} split</div>}
237	                      </>
238	                    );
239	                  })()}
240	                  <StatusBox status={invoiceStatus(inv)} />
241	                </div>
242	              </div>
243	            );
244	          })}
245	        </div>
246	      )}
247	    </div>
248	    </div>
249	  );
250	}
